class Battle::Move::WeatherMove < Battle::Move
  attr_reader :weatherType

  def initialize(battle, move)
    super
    @weatherType = :None
  end

  def pbMoveFailed?(user, targets)
    case @battle.field.weather
    when :HarshSun
      @battle.pbDisplay(_INTL("The extremely harsh sunlight was not lessened at all!"))
      return true
    when :HeavyRain
      @battle.pbDisplay(_INTL("There is no relief from this heavy rain!"))
      return true
    when :StrongWinds
      @battle.pbDisplay(_INTL("The mysterious air current blows on regardless!"))
      return true
    when @weatherType
      @battle.pbDisplay(_INTL("But it failed!"))
      return true
    end
    return false
  end

  def pbEffectGeneral(user)
    @battle.pbStartWeather(user, @weatherType, true, false)
  end
end

def eachBattler
  @battlers.each { |b| yield b if b && !b.fainted? }
end

def allBattlers
  return @battlers.select { |b| b && !b.fainted? }
end

# Unused
def eachSameSideBattler(idxBattler = 0)
  idxBattler = idxBattler.index if idxBattler.respond_to?("index")
  @battlers.each { |b| yield b if b && !b.fainted? && !b.opposes?(idxBattler) }
end

def allSameSideBattlers(idxBattler = 0)
  idxBattler = idxBattler.index if idxBattler.respond_to?("index")
  return @battlers.select { |b| b && !b.fainted? && !b.opposes?(idxBattler) }
end

# Unused
def eachOtherSideBattler(idxBattler = 0)
  idxBattler = idxBattler.index if idxBattler.respond_to?("index")
  @battlers.each { |b| yield b if b && !b.fainted? && b.opposes?(idxBattler) }
end

def allOtherSideBattlers(idxBattler = 0)
  idxBattler = idxBattler.index if idxBattler.respond_to?("index")
  return @battlers.select { |b| b && !b.fainted? && b.opposes?(idxBattler) }
end

def pbSideBattlerCount(idxBattler = 0)
  return allSameSideBattlers(idxBattler).length
end

def pbOpposingBattlerCount(idxBattler = 0)
  return allOtherSideBattlers(idxBattler).length
end

# This method only counts the player's Pokémon, not a partner trainer's.
def pbPlayerBattlerCount
  return allSameSideBattlers.select { |b| b.pbOwnedByPlayer? }.length
end

def pbCheckGlobalAbility(abil)
  allBattlers.each { |b| return b if b.hasActiveAbility?(abil) }
  return nil
end

def takesIndirectDamage?(showMsg = false)
  return false if fainted?
  if hasActiveAbility?(:MAGICGUARD)
    if showMsg
      @battle.pbShowAbilitySplash(self)
      if Battle::Scene::USE_ABILITY_SPLASH
        @battle.pbDisplay(_INTL("{1} is unaffected!", pbThis))
      else
        @battle.pbDisplay(_INTL("{1} is unaffected because of its {2}!", pbThis, abilityName))
      end
      @battle.pbHideAbilitySplash(self)
    end
    return false
  end
  return true
end

def abilityActive?(ignore_fainted = false, check_ability = nil)
  return false if fainted? && !ignore_fainted
  return false if @effects[PBEffects::GastroAcid]
  return false if check_ability != :NEUTRALIZINGGAS && self.ability != :NEUTRALIZINGGAS &&
                  @battle.pbCheckGlobalAbility(:NEUTRALIZINGGAS)
  return true
end

def hasActiveAbility?(check_ability, ignore_fainted = false)
  return false if !abilityActive?(ignore_fainted, check_ability)
  return check_ability.include?(@ability_id) if check_ability.is_a?(Array)
  return self.ability == check_ability
end
alias hasWorkingAbility hasActiveAbility?

def itemActive?(ignoreFainted = false)
  return false if fainted? && !ignoreFainted
  return false if @effects[PBEffects::Embargo] > 0
  return false if @battle.field.effects[PBEffects::MagicRoom] > 0
  return false if @battle.corrosiveGas[@index % 2][@pokemonIndex]
  return false if hasActiveAbility?(:KLUTZ, ignoreFainted)
  return true
end

def hasActiveItem?(check_item, ignore_fainted = false)
  return false if !itemActive?(ignore_fainted)
  return check_item.include?(@item_id) if check_item.is_a?(Array)
  return self.item == check_item
end
alias hasWorkingItem hasActiveItem?

# Returns whether the specified item will be unlosable for this Pokémon.

def hp=(value)
  @hp = value.to_i
  @pokemon.hp = value.to_i if @pokemon
end

def fainted?; return @hp <= 0; end

def form=(value)
  @form = value
  @pokemon.form = value if @pokemon
end

def pbChangeForm(newForm, msg)
  return if fainted? || @effects[PBEffects::Transform] || @form == newForm
  oldForm = @form
  oldDmg = @totalhp - @hp
  self.form = newForm
  pbUpdate(true)
  @hp = @totalhp - oldDmg
  @effects[PBEffects::WeightChange] = 0 if Settings::MECHANICS_GENERATION >= 6
  @battle.scene.pbChangePokemon(self, @pokemon)
  @battle.scene.pbRefreshOne(@index)
  @battle.pbDisplay(msg) if msg && msg != ""
  PBDebug.log("[Form changed] #{pbThis} changed from form #{oldForm} to form #{newForm}")
  @battle.pbSetSeen(self)
end

def pbUpdate(fullChange = false)
  return if !@pokemon
  @pokemon.calc_stats
  @level          = @pokemon.level
  @hp             = @pokemon.hp
  @totalhp        = @pokemon.totalhp
  if !@effects[PBEffects::Transform]
    @attack       = @pokemon.attack
    @defense      = @pokemon.defense
    @spatk        = @pokemon.spatk
    @spdef        = @pokemon.spdef
    @speed        = @pokemon.speed
    if fullChange
      @types      = @pokemon.types
      @ability_id = @pokemon.ability_id
    end
  end
end

